import { DeleteObjectCommand, PutObjectCommand, S3Client } from '@aws-sdk/client-s3';
import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, join, resolve } from 'node:path';
import { loadEnv } from '../../config/env.js';

/** Storage backends. Keys are always generated by the API (never from user input). */
export interface MediaStorage {
  put(key: string, body: Buffer, contentType: string): Promise<string>; // returns public URL
  remove(key: string): Promise<void>;
}

/** Development / single-server: files on disk, served by the API at /media/<key without "tenants/">. */
export class LocalStorage implements MediaStorage {
  readonly root = resolve(loadEnv().MEDIA_LOCAL_DIR);

  async put(key: string, body: Buffer) {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, body, { flag: 'wx' });
    return `/media/${key.replace(/^tenants\//, '')}`;
  }

  async remove(key: string) {
    await rm(this.pathFor(key), { force: true });
  }

  private pathFor(key: string) {
    const path = resolve(join(this.root, key));
    if (!path.startsWith(this.root + '/')) throw new Error('Invalid media key');
    return path;
  }
}

/** Production: any S3-compatible bucket (AWS S3, Cloudflare R2, Spaces, MinIO) behind a CDN. */
export class S3Storage implements MediaStorage {
  private readonly env = loadEnv();
  private readonly client = new S3Client({
    region: this.env.S3_REGION,
    endpoint: this.env.S3_ENDPOINT,
    forcePathStyle: !!this.env.S3_ENDPOINT,
    credentials: { accessKeyId: this.env.S3_ACCESS_KEY_ID!, secretAccessKey: this.env.S3_SECRET_ACCESS_KEY! },
  });

  async put(key: string, body: Buffer, contentType: string) {
    await this.client.send(
      new PutObjectCommand({
        Bucket: this.env.S3_BUCKET, Key: key, Body: body, ContentType: contentType,
        CacheControl: 'public, max-age=31536000, immutable',
      }),
    );
    return `${this.env.S3_PUBLIC_BASE_URL!.replace(/\/$/, '')}/${key}`;
  }

  async remove(key: string) {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.env.S3_BUCKET, Key: key }));
  }
}

export function createStorage(): MediaStorage {
  return loadEnv().MEDIA_DRIVER === 's3' ? new S3Storage() : new LocalStorage();
}
